// ---- business-day deadlines: rules from words, dates by code --------------------------------------------------
const nfkc = (s) => String(s ?? '').normalize('NFKC');
const isoOf = (y, m, d) => { const t = new Date(Date.UTC(y, m - 1, d)); return t.getUTCFullYear() === y && t.getUTCMonth() === m - 1 && t.getUTCDate() === d ? t.toISOString().slice(0, 10) : ''; };
const addDays = (iso, n) => new Date(Date.parse(iso + 'T00:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const weekday = (iso) => new Date(iso + 'T00:00:00Z').getUTCDay(); // 0 = Sunday
function parseDate(v) {
  if (/^\d{5}(\.\d+)?$/.test(String(v).trim()) && Number(v) > 20000 && Number(v) < 80000) return new Date(Date.UTC(1899, 11, 30) + Math.floor(Number(v)) * 86400000).toISOString().slice(0, 10);
  const m = nfkc(v).trim().match(/(\d{4})\s*[-\/.年]\s*(\d{1,2})\s*[-\/.月]\s*(\d{1,2})/);
  return m ? isoOf(+m[1], +m[2], +m[3]) : '';
}
const KD = { 〇: 0, 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };
function kanjiValue(run) {
  if (!/[十百]/.test(run)) return Number([...run].map((c) => KD[c]).join(''));
  let total = 0, cur = 0;
  for (const c of run) { if (c in KD) cur = KD[c]; else { total += (cur || 1) * (c === '十' ? 10 : 100); cur = 0; } }
  return total + cur;
}
function numbersIn(text) {
  const s = new Set((nfkc(text).match(/\d+/g) ?? []).map(String));
  for (const r of nfkc(text).match(/[〇一二三四五六七八九十百]+/g) ?? []) s.add(String(kanjiValue(r)));
  return s;
}

// holidays: the Cabinet Office CSV (Shift_JIS text already decoded) + extra company days
function holidaySet(csvText, extra) {
  const s = new Set();
  for (const line of String(csvText ?? '').split(/\r?\n/)) { const d = parseDate(line.split(',')[0]); if (d) s.add(d); }
  for (const x of String(extra ?? '').split(/[\s,、]+/)) { const d = parseDate(x); if (d) s.add(d); }
  return s;
}
const isBusinessDay = (iso, hol, weekendDays) => !weekendDays.includes(weekday(iso)) && !hol.has(iso);
function adjust(iso, how, hol, wk) {
  if (how === 'none' || isBusinessDay(iso, hol, wk)) return iso;
  let d = iso;
  for (let i = 0; i < 31 && !isBusinessDay(d, hol, wk); i++) d = addDays(d, how === 'next' ? 1 : -1);
  return d;
}
// the deadline from a rule (the base day is not counted)
function computeDeadline(base, rule, hol, wk) {
  if (rule.type === 'business_days_after') {
    let d = base, n = 0;
    for (let i = 0; i < 400 && n < rule.n; i++) { d = addDays(d, 1); if (isBusinessDay(d, hol, wk)) n++; }
    return d;
  }
  if (rule.type === 'calendar_days_after') return adjust(addDays(base, rule.n), rule.adjust, hol, wk);
  if (rule.type === 'day_of_month') {
    const [y, m] = base.split('-').map(Number);
    const t = new Date(Date.UTC(y, m - 1 + rule.months_after, 1));
    const yy = t.getUTCFullYear(), mm = t.getUTCMonth() + 1;
    const last = new Date(Date.UTC(yy, mm, 0)).getUTCDate();
    const day = rule.day === 'end' ? last : Math.min(Number(rule.day), last);
    return adjust(isoOf(yy, mm, day), rule.adjust, hol, wk);
  }
  return '';
}
// business days from today to the deadline (0 = today, negative = overdue)
function businessDaysLeft(today, deadline, hol, wk) {
  if (deadline === today) return 0;
  const step = deadline > today ? 1 : -1;
  let d = today, n = 0;
  for (let i = 0; i < 800 && d !== deadline; i++) { d = addDays(d, step); if (isBusinessDay(d, hol, wk)) n += step; }
  return n;
}

// check Claude's rule against the wording; fill in the default adjustment when the wording says nothing
function checkRule(raw, text, cfg) {
  let r = null;
  try {
    const t = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const a = t.indexOf('{'), z = t.lastIndexOf('}');
    r = JSON.parse(a >= 0 && z > a ? t.slice(a, z + 1) : t);
  } catch (e) { r = null; }
  if (!r) return { rule: null, problems: ['the AI output could not be read as JSON'] };
  const w = nfkc(text).toLowerCase();
  const nums = numbersIn(text);
  const problems = [];
  const types = ['business_days_after', 'calendar_days_after', 'day_of_month'];
  if (!types.includes(r.type)) return { rule: null, problems: ['the wording could not be turned into a rule' + (r.reason ? ' (' + r.reason + ')' : '')] };
  const rule = { type: r.type };
  if (r.type !== 'day_of_month') {
    rule.n = Number(r.n);
    if (!(rule.n > 0 && rule.n < 400)) problems.push('the number of days is missing');
    else if (!nums.has(String(rule.n))) problems.push('the number ' + rule.n + ' is not in the wording');
    if (r.type === 'business_days_after' && !/営業日|business day|working day/.test(w)) problems.push('the wording does not say business days');
  } else {
    rule.months_after = Number(r.months_after);
    rule.day = r.day === 'end' ? 'end' : Number(r.day);
    if (!(rule.months_after >= 0 && rule.months_after <= 12)) problems.push('the month offset is missing');
    const monthWords = { 0: /当月|今月|同月|this month|same month/, 1: /翌月|次月|来月|next month|following month/, 2: /翌々月|2\s*か月後|month after next/ };
    if (monthWords[rule.months_after] && !monthWords[rule.months_after].test(w) && !(rule.months_after === 1 && /翌々月/.test(w) === false && /1\s*か月/.test(w))) problems.push('the month offset ' + rule.months_after + ' does not match the wording');
    if (rule.months_after === 1 && /翌々月/.test(w)) problems.push('the wording says the month after next');
    if (rule.day === 'end') { if (!/末|end of/.test(w)) problems.push('the wording does not say the end of the month'); }
    else if (!(rule.day >= 1 && rule.day <= 31)) problems.push('the day is missing');
    else if (!nums.has(String(rule.day))) problems.push('the day ' + rule.day + ' is not in the wording');
  }
  const says = /前営業日|繰り上げ|前倒し|preceding|previous business/.test(w) ? 'previous' : /翌営業日|繰り下げ|following business|next business/.test(w) ? 'next' : '';
  rule.adjust = r.type === 'business_days_after' ? 'none' : (says || cfg.default_adjust || 'previous');
  if (says && r.adjust && r.adjust !== says && r.type !== 'business_days_after') problems.push('the AI read the holiday rule as "' + r.adjust + '", the wording says "' + says + '"');
  rule.note = says || r.type === 'business_days_after' ? '' : 'holiday rule not in the wording: ' + rule.adjust + ' (Config)';
  return { rule, problems };
}

function describeRule(rule, ja) {
  if (!rule) return '';
  const adj = { previous: ja ? '休日なら前の営業日' : 'previous business day if closed', next: ja ? '休日なら次の営業日' : 'next business day if closed', none: '' }[rule.adjust];
  if (rule.type === 'business_days_after') return ja ? '起点の日から' + rule.n + '営業日後' : rule.n + ' business days after the base date';
  if (rule.type === 'calendar_days_after') return (ja ? '起点の日から' + rule.n + '日後' : rule.n + ' days after the base date') + (adj ? (ja ? '（' + adj + '）' : ' (' + adj + ')') : '');
  const mo = ja ? ['当月', '翌月', '翌々月'][rule.months_after] ?? rule.months_after + 'か月後' : ['this month', 'next month', 'the month after next'][rule.months_after] ?? rule.months_after + ' months later';
  return (ja ? mo + 'の' + (rule.day === 'end' ? '末日' : rule.day + '日') : (rule.day === 'end' ? 'the last day of ' : 'day ' + rule.day + ' of ') + mo) + (adj ? (ja ? '（' + adj + '）' : ' (' + adj + ')') : '');
}

const cfg = $('Config').first().json;
// the Cabinet Office CSV is Shift_JIS
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const csv = new TextDecoder('shift_jis').decode(buf);
const hol = [...holidaySet(csv, cfg.extra_holidays)];
if (hol.length < 100) throw new Error('The holiday list looks wrong (' + hol.length + ' dates). Check holiday_csv_url in Config.');
const rows = $('Read Deadlines tab').all().map((i) => i.json).filter((r) => String(r.task ?? '').trim() && String(r.status ?? '').toLowerCase() !== 'done');
return rows.map((r) => ({ json: { ...r, base_iso: parseDate(r.base_date), needs_rule: !String(r.rule_source ?? '').trim() || String(r.rule_source) !== String(r.rule_text ?? ''), holidays: hol } }));

values.content:
=Turn the wording of a deadline into a rule. Use ONLY the wording. Do not compute any date.

# Rule types
- "business_days_after": N business days after the base date. Fields: n.
- "calendar_days_after": N calendar days after the base date. Fields: n, adjust.
- "day_of_month": a day in this month (months_after 0), next month (1) or the month after next (2). Fields: months_after, day (a number, or "end" for the last day), adjust.
- adjust: "previous" (if the date is a holiday, use the business day before), "next" (the business day after), or "" if the wording does not say.
- If the wording fits none of the types, return {"type": "unknown", "reason": "..."}.

# Examples
"受領日から10営業日以内" -> {"type": "business_days_after", "n": 10}
"月末締め翌月20日払い（休日の場合は前営業日）" -> {"type": "day_of_month", "months_after": 1, "day": 20, "adjust": "previous"}
"翌月末" -> {"type": "day_of_month", "months_after": 1, "day": "end", "adjust": ""}
"within 30 days of the invoice date" -> {"type": "calendar_days_after", "n": 30, "adjust": ""}

Output JSON only (no explanation, no code block).

# Wording
{{ $json.rule_text }}

