  // the same wording as last time: reuse the stored rule (or the stored reason it could not be read), no AI call
  if (!r.rule_new && !String(r.rule ?? '').trim()) problems.push(String(r.problems ?? '').trim() || 'no rule for this wording (clear rule_source to ask the AI again)');
  else if (!r.rule_new) { try { rule = JSON.parse(r.rule); } catch (e) { rule = null; problems.push('the stored rule could not be read'); } }
  if (!r.base_iso) problems.push('base_date is not a date (year first, like 2026-10-15)');
  const deadline = rule && r.base_iso ? computeDeadline(r.base_iso, rule, hol, wk) : '';
  const left = deadline ? businessDaysLeft(today, deadline, hol, wk) : '';
