    deadline, business_days_left: left, check, problems: [...new Set(problems.flatMap((p) => String(p).split('; ')))].join('; '), checked_at: $now.toISO() } };
});

const cfg = $('Config').first().json;
const ja = String(cfg.language).startsWith('ja');
const rows = $input.all().map((i) => i.json);
const n = Number(cfg.remind_business_days);
const who = (r) => (r.owner ? (/^[UW][A-Z0-9]{6,}$/.test(r.owner) ? ' <@' + r.owner + '>' : ' ' + r.owner) : '');
const line = (r) => '• ' + r.task + who(r) + ' — ' + r.deadline + (ja ? '（' + r.rule_plain + '）' : ' (' + r.rule_plain + ')');
const over = rows.filter((r) => r.deadline && r.business_days_left < 0), today = rows.filter((r) => r.deadline && r.business_days_left === 0);
const soon = rows.filter((r) => r.deadline && r.business_days_left > 0 && r.business_days_left <= n), review = rows.filter((r) => r.check !== 'OK');
const parts = [];
if (over.length) parts.push((ja ? ':red_circle: *期限切れ*\n' : ':red_circle: *Overdue*\n') + over.map((r) => line(r) + (ja ? ' ' + -r.business_days_left + '営業日超過' : ' ' + -r.business_days_left + ' business days late')).join('\n'));
if (today.length) parts.push((ja ? ':large_orange_circle: *今日が期限*\n' : ':large_orange_circle: *Due today*\n') + today.map(line).join('\n'));
if (soon.length) parts.push((ja ? ':large_yellow_circle: *' + n + '営業日以内*\n' : ':large_yellow_circle: *Within ' + n + ' business days*\n') + soon.map((r) => line(r) + (ja ? ' あと' + r.business_days_left + '営業日' : ' ' + r.business_days_left + ' left')).join('\n'));
if (review.length) parts.push((ja ? ':warning: *期限の書き方を確かめてください*\n' : ':warning: *Check the deadline wording*\n') + review.map((r) => '• ' + r.task + ' — ' + r.problems).join('\n'));
if (!parts.length) return [];
return [{ json: { text: (ja ? '*期限の見張り* ' : '*Deadline watch* ') + $now.toFormat('yyyy-MM-dd') + '\n' + parts.join('\n') } }];
